cat > app.test.mjs <<'EOF'
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import test from 'node:test';

const exportCsv = (values, variant) => execFileSync(process.execPath,
  ['app.mjs', JSON.stringify(values), ...(variant ? [variant] : [])],
  { encoding: 'utf8', cwd: new URL('.', import.meta.url) });

test('default preserves Unicode and column order while escaping CSV fields', () => {
  assert.equal(exportCsv(['Zoë', '東京', 'Lee, Sam', 'say "hi"', '', 'last']),
    'Zoë,東京,"Lee, Sam","say ""hi""",,last\n');
});

test('quotes line breaks, including carriage returns', () => {
  assert.equal(exportCsv(['a\nb', 'c\rd', 'e\r\nf']),
    '"a\nb","c\rd","e\r\nf"\n');
});

test('preserves empty fields and string conversion', () => {
  assert.equal(exportCsv(['', 0, false, null, '']), ',0,false,null,\n');
  assert.equal(exportCsv([]), '\n');
});

test('explicit component configurations remain available', () => {
  const values = ['Zoë', 'a,b'];
  assert.equal(exportCsv(values, 'full'), 'Zoë,"a,b"\n');
  assert.equal(exportCsv(values, 'baseline'), 'Zo,a,b\n');
  assert.equal(exportCsv(values, 'without-unicode'), 'Zo,"a,b"\n');
  assert.equal(exportCsv(values, 'without-escaping'), 'Zoë,a,b\n');
});
EOF
